            try {
                if (item.locked === true) {
                    fail("The cover frame or a parent group is locked. Unlock it and run the script again.");
                }
            } catch (error2) {
                if (error2.message && error2.message.indexOf("is locked") >= 0) { throw error2; }
            }
            try { item = item.parent; } catch (ignore) { item = null; }
